package main

const adminHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FamilyGuard 平台管理</title><style>
:root{font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;color:#182941;background:#f5f8fd}*{box-sizing:border-box}body{margin:0}header{background:white;border-bottom:1px solid #dce6f1;padding:24px max(24px,calc((100% - 940px)/2))}main{max-width:940px;margin:28px auto;padding:0 20px}.muted{color:#60748c;font-size:14px}.panel{background:white;border:1px solid #e1e9f2;border-radius:18px;padding:24px;margin:16px 0;box-shadow:0 5px 20px #14304e0d}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:14px}.metric{border:1px solid #dce5f0;border-radius:14px;padding:20px}.metric strong{font-size:34px;display:block;margin-bottom:6px}input{font:inherit;border:1px solid #b6c7da;border-radius:12px;padding:13px;width:100%;max-width:460px}button{background:#2667ce;color:#fff;font:inherit;border:0;padding:12px 23px;border-radius:12px;margin:12px 0;cursor:pointer}button:hover{background:#194da0}#error{color:#a61d29}#stats{display:none}h1{font-size:24px;margin:0}h2{font-size:19px}</style></head><body><header><h1>FamilyGuard 平台概况</h1><div class="muted">管理统计，不显示任何儿童位置、音视频或个人资料</div></header><main><section class="panel"><h2>管理员身份验证</h2><p class="muted">输入独立的平台管理员令牌。令牌只保留在当前页面内存，不存入浏览器。</p><input type="password" id="token" autocomplete="off" placeholder="平台管理员令牌"><div><button id="load">查看平台概况</button></div><div id="error" role="alert"></div></section><section id="stats" class="panel"><h2>服务概况</h2><div class="grid"><div class="metric"><strong id="families">—</strong>独立家庭</div><div class="metric"><strong id="children">—</strong>孩子设备</div><div class="metric"><strong id="guardians">—</strong>其他监护人</div></div><p class="muted" id="mode"></p></section></main><script src="/v1/admin/dashboard.js"></script></body></html>`
const adminJS = `(()=>{'use strict';const $=id=>document.getElementById(id);$('load').addEventListener('click',async()=>{const token=$('token').value.trim();$('error').textContent='';$('stats').style.display='none';if(token.length<32){$('error').textContent='请输入有效的管理员令牌';return;}try{const r=await fetch('/v1/admin/stats',{cache:'no-store',headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error('验证失败或管理服务不可用');const v=await r.json();$('families').textContent=String(v.families);$('children').textContent=String(v.childDevices);$('guardians').textContent=String(v.guardians);$('mode').textContent=v.registrationEnabled?'家庭自主创建已启用（'+v.registrationMode+'）':'家庭自主创建尚未启用';$('stats').style.display='block';$('token').value='';}catch(e){$('error').textContent=e.message;}})})();`
